    std::shared_ptr<gf::EasingPreview> preview =
        gf::make_control<gf::EasingPreview>(gf::StableId("motion.preview"));
    (*preview).set_requested_bounds({0.0, 0.0, 480.0, 160.0});
    std::vector<gf::EasingPreviewTrack> tracks;
